41	export type NotificationType =
42	  | 'scan_complete'
43	  | 'score_improved'
44	  | 'score_dropped'
45	  | 'team_invite'
46	  | 'finding_reappeared'
47	  | 'system'
48	  | 'score_drop'
49	  | 'weekly_digest'
