1	/**
2	 * slack-oauth — Edge Function
3	 *
4	 * Handles the OAuth 2.0 callback from Slack after user authorizes the app.
5	 * Exchanges the one-time code for an access token and stores it in the
6	 * integrations table, then redirects the user back to the app.
7	 *
8	 * Flow:
9	 *   User clicks "Connect Slack" → redirected to Slack OAuth page
10	 *   → Slack redirects to this function with ?code=xxx&state=user_id
11	 *   → Function exchanges code for access_token
12	 *   → Stores integration row in Supabase
13	 *   → Redirects user to /integrations?slack=connected
14	 *
15	 * Required env vars:
16	 *   SLACK_CLIENT_ID        — Slack app client ID
17	 *   SLACK_CLIENT_SECRET    — Slack app client secret
18	 *   SUPABASE_URL           — Supabase project URL (auto-injected by Supabase)
19	 *   SUPABASE_SERVICE_ROLE_KEY — Service role key (auto-injected by Supabase)
20	 *   SITE_URL               — Frontend URL, e.g. https://app.convertscan.com
21	 */
22	
23	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
24	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
25	
26	// ── CORS headers ──────────────────────────────────────────────
27	
28	const corsHeaders = {
29	  "Access-Control-Allow-Origin": "*",
30	  "Access-Control-Allow-Headers":
31	    "authorization, x-client-info, apikey, content-type",
32	  "Access-Control-Allow-Methods": "GET, OPTIONS",
33	};
34	
35	// ── Slack OAuth token response shape ─────────────────────────
36	
37	interface SlackOAuthResponse {
38	  ok: boolean;
39	  error?: string;
40	  access_token?: string;
41	  token_type?: string;
42	  scope?: string;
43	  bot_user_id?: string;
44	  app_id?: string;
45	  team?: { id: string; name: string };
46	  authed_user?: { id: string };
47	  incoming_webhook?: {
48	    channel: string;
49	    channel_id: string;
50	    configuration_url: string;
51	    url: string;
52	  };
53	}
54	
55	// ── Handler ───────────────────────────────────────────────────
56	
57	serve(async (req: Request) => {
58	  if (req.method === "OPTIONS") {
59	    return new Response("ok", { headers: corsHeaders });
60	  }
61	
62	  const siteUrl = Deno.env.get("SITE_URL") ?? "http://localhost:8080";
63	  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
64	  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
65	  const clientId = Deno.env.get("SLACK_CLIENT_ID") ?? "";
66	  const clientSecret = Deno.env.get("SLACK_CLIENT_SECRET") ?? "";
67	
68	  // Only accept GET (Slack sends a redirect)
69	  if (req.method !== "GET") {
70	    return Response.redirect(`${siteUrl}/integrations?slack=error`, 302);
71	  }
72	
73	  const reqUrl = new URL(req.url);
74	  const code = reqUrl.searchParams.get("code");
75	  const state = reqUrl.searchParams.get("state"); // user_id passed as state
76	
77	  // Validate required params
78	  if (!code || !state) {
79	    console.error("slack-oauth: missing code or state param");
80	    return Response.redirect(`${siteUrl}/integrations?slack=error`, 302);
81	  }
82	
83	  // Exchange code for access token
84	  const redirectUri = `${supabaseUrl}/functions/v1/slack-oauth`;
85	
86	  let oauthData: SlackOAuthResponse;
87	  try {
88	    const tokenRes = await fetch("https://slack.com/api/oauth.v2.access", {
89	      method: "POST",
90	      headers: { "Content-Type": "application/x-www-form-urlencoded" },
91	      body: new URLSearchParams({
92	        client_id: clientId,
93	        client_secret: clientSecret,
94	        code,
95	        redirect_uri: redirectUri,
96	      }),
97	    });
98	
99	    if (!tokenRes.ok) {
100	      console.error("slack-oauth: Slack API HTTP error", tokenRes.status);
101	      return Response.redirect(`${siteUrl}/integrations?slack=error`, 302);
102	    }
103	
104	    oauthData = (await tokenRes.json()) as SlackOAuthResponse;
105	  } catch (err) {
106	    console.error("slack-oauth: token exchange fetch failed", err);
107	    return Response.redirect(`${siteUrl}/integrations?slack=error`, 302);
108	  }
109	
110	  if (!oauthData.ok || !oauthData.access_token) {
111	    console.error("slack-oauth: Slack returned error:", oauthData.error);
112	    return Response.redirect(`${siteUrl}/integrations?slack=error`, 302);
113	  }
114	
115	  // Persist integration to Supabase using service role (bypasses RLS)
116	  const supabase = createClient(supabaseUrl, serviceRoleKey);
117	
118	  const metadata: Record<string, unknown> = {
119	    team_id: oauthData.team?.id ?? null,
120	    team_name: oauthData.team?.name ?? null,
121	    scope: oauthData.scope ?? null,
122	    bot_user_id: oauthData.bot_user_id ?? null,
123	    app_id: oauthData.app_id ?? null,
124	    // Store incoming webhook channel if present (incoming-webhook scope)
125	    channel_id: oauthData.incoming_webhook?.channel_id ?? null,
126	    channel: oauthData.incoming_webhook?.channel ?? null,
127	    webhook_url: oauthData.incoming_webhook?.url ?? null,
128	  };
129	
130	  const { error: upsertError } = await supabase
131	    .from("integrations")
132	    .upsert(
133	      {
134	        user_id: state,
135	        provider: "slack",
136	        access_token: oauthData.access_token,
137	        is_active: true,
138	        metadata,
139	      },
140	      { onConflict: "user_id,provider" },
141	    );
142	
143	  if (upsertError) {
144	    console.error("slack-oauth: failed to upsert integration row", upsertError);
145	    return Response.redirect(`${siteUrl}/integrations?slack=error`, 302);
146	  }
147	
148	  return Response.redirect(`${siteUrl}/integrations?slack=connected`, 302);
149	});
