389	  const Icon = SLACK_CONFIG.icon;
390	  const disconnectIntegration = useDisconnectIntegration();
391	
392	  const slackClientId = import.meta.env.VITE_SLACK_CLIENT_ID as string | undefined;
393	  const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string | undefined;
394	
395	  const handleConnect = () => {
396	    if (!slackClientId || !supabaseUrl) {
397	      toast.error("Slack integration is not configured yet. Check back soon.");
398	      return;
399	    }
400	    const redirectUri = encodeURIComponent(`${supabaseUrl}/functions/v1/slack-oauth`);
401	    const scopes = encodeURIComponent("chat:write,chat:write.public");
402	    const oauthUrl = `https://slack.com/oauth/v2/authorize?client_id=${slackClientId}&scope=${scopes}&redirect_uri=${redirectUri}&state=${encodeURIComponent(userId)}`;
403	    window.location.href = oauthUrl;
