2	import supabase from "@/lib/supabase";
3	import { useAuth } from "@/contexts/AuthContext";
4	import type { IntegrationRow } from "@/types/database";
5	
6	// ── Types ─────────────────────────────────────────────────────
7	
8	export type IntegrationProvider = IntegrationRow["provider"];
9	
10	interface ConnectIntegrationInput {
11	  provider: IntegrationProvider;
12	  trackingId: string;
13	}
14	
15	interface DisconnectIntegrationInput {
16	  provider: IntegrationProvider;
17	}
18	
19	// ── Query keys ─────────────────────────────────────────────────
20	
21	export const integrationKeys = {
22	  all: ["integrations"] as const,
23	};
24	
25	// ── useIntegrations ────────────────────────────────────────────
26	// Fetches all integrations for the current user.
27	
28	export function useIntegrations() {
29	  const { profile } = useAuth();
30	  const userId = profile?.id;
31	
32	  return useQuery({
33	    queryKey: integrationKeys.all,
34	    queryFn: async (): Promise<IntegrationRow[]> => {
35	      if (!userId) return [];
36	
37	      const { data, error } = await supabase
38	        .from("integrations")
39	        .select("*")
40	        .eq("user_id", userId)
41	        .order("connected_at", { ascending: false });
42	
43	      if (error) throw new Error(error.message);
44	      return data as IntegrationRow[];
45	    },
46	    enabled: !!userId,
47	    staleTime: 1000 * 60, // 1 minute
48	  });
49	}
50	
51	// ── useConnectIntegration ──────────────────────────────────────
52	// Upserts an integration row. Creates on first connect, updates on reconnect.
53	
54	export function useConnectIntegration() {
55	  const { profile } = useAuth();
56	  const queryClient = useQueryClient();
57	
58	  return useMutation({
59	    mutationFn: async ({ provider, trackingId }: ConnectIntegrationInput): Promise<IntegrationRow> => {
60	      const userId = profile?.id;
61	      if (!userId) throw new Error("Not authenticated");
62	
63	      const { data, error } = await supabase
64	        .from("integrations")
65	        .upsert(
66	          {
67	            user_id: userId,
68	            provider,
69	            access_token: trackingId,
70	            is_active: true,
71	          },
72	          { onConflict: "user_id,provider" }
73	        )
74	        .select("*")
75	        .single();
76	
77	      if (error) throw new Error(error.message);
78	      return data as IntegrationRow;
79	    },
80	    onSuccess: () => {
81	      queryClient.invalidateQueries({ queryKey: integrationKeys.all });
82	    },
83	  });
84	}
85	
86	// ── useDisconnectIntegration ───────────────────────────────────
87	// Marks an integration as inactive and clears the stored token.
88	
89	export function useDisconnectIntegration() {
90	  const { profile } = useAuth();
91	  const queryClient = useQueryClient();
92	
93	  return useMutation({
94	    mutationFn: async ({ provider }: DisconnectIntegrationInput): Promise<void> => {
95	      const userId = profile?.id;
96	      if (!userId) throw new Error("Not authenticated");
97	
98	      const { error } = await supabase
99	        .from("integrations")
100	        .update({ is_active: false, access_token: null })
101	        .eq("user_id", userId)
102	        .eq("provider", provider);
103	
104	      if (error) throw new Error(error.message);
105	    },
106	    onSuccess: () => {
107	      queryClient.invalidateQueries({ queryKey: integrationKeys.all });
108	    },
109	  });
