input.content:
/**
 * ga4-oauth — Edge Function
 *
 * Handles the OAuth 2.0 callback from Google after the user authorizes GA4 access.
 * Exchanges the one-time code for access_token + refresh_token and stores them in
 * the integrations table, then redirects back to the app.
 *
 * Flow:
 *   User clicks "Connect with Google" → redirected to Google OAuth page
 *   → Google redirects to this function with ?code=xxx&state=user_id
 *   → Function exchanges code for access_token + refresh_token
 *   → Stores integration row in Supabase (upsert on user_id,provider)
 *   → Redirects user to /integrations?ga4=connected
 *
 * Required env vars:
 *   GOOGLE_CLIENT_ID           — Google OAuth 2.0 client ID
 *   GOOGLE_CLIENT_SECRET       — Google OAuth 2.0 client secret
 *   SUPABASE_URL               — Supabase project URL (auto-injected)
 *   SUPABASE_SERVICE_ROLE_KEY  — Service role key (auto-injected)
 *   SITE_URL                   — Frontend URL, e.g. https://app.convertscan.com
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

// ── CORS headers ──────────────────────────────────────────────

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
};

// ── Google token response shape ───────────────────────────────

interface GoogleTokenResponse {
  access_token?: string;
  refresh_token?: string;
  expires_in?: number;
  token_type?: string;
  scope?: string;
  error?: string;
  error_description?: string;
}

// ── Handler ───────────────────────────────────────────────────

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  const siteUrl = Deno.env.get("SITE_URL") ?? "http://localhost:8080";
  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  const clientId = Deno.env.get("GOOGLE_CLIENT_ID") ?? "";
  const clientSecret = Deno.env.get("GOOGLE_CLIENT_SECRET") ?? "";

  // Only accept GET (Google sends a redirect)
  if (req.method !== "GET") {
    return Response.redirect(`${siteUrl}/integrations?ga4=error`, 302);
  }

  const reqUrl = new URL(req.url);
  const code = reqUrl.searchParams.get("code");
  const state = reqUrl.searchParams.get("state"); // user_id passed as state

  // Validate required params
  if (!code || !state) {
    console.error("ga4-oauth: missing code or state param");
    return Response.redirect(`${siteUrl}/integrations?ga4=error`, 302);
  }

  const redirectUri = `${supabaseUrl}/functions/v1/ga4-oauth`;

  let tokenData: GoogleTokenResponse;
  try {
    const tokenRes = await fetch("https://oauth2.googleapis.com/token", {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        code,
        client_id: clientId,
        client_secret: clientSecret,
        redirect_uri: redirectUri,
        grant_type: "authorization_code",
      }),
    });

    if (!tokenRes.ok) {
      console.error("ga4-oauth: Google token endpoint HTTP error", tokenRes.status);
      return Response.redirect(`${siteUrl}/integrations?ga4=error`, 302);
    }

    tokenData = (await tokenRes.json()) as GoogleTokenResponse;
  } catch (err) {
    console.error("ga4-oauth: token exchange fetch failed", err);
    return Response.redirect(`${siteUrl}/integrations?ga4=error`, 302);
  }

  if (tokenData.error || !tokenData.access_token) {
    console.error("ga4-oauth: Google returned error:", tokenData.error, tokenData.error_description);
    return Response.redirect(`${siteUrl}/integrations?ga4=error`, 302);
  }

  // Persist integration to Supabase using service role (bypasses RLS)
  const supabase = createClient(supabaseUrl, serviceRoleKey);

  const metadata: Record<string, unknown> = {
    scope: tokenData.scope ?? null,
    token_type: tokenData.token_type ?? null,
    expires_in: tokenData.expires_in ?? null,
    // ga4_property_id stored here when user sets it up post-connect
    ga4_property_id: null,
  };

  const { error: upsertError } = await supabase
    .from("integrations")
    .upsert(
      {
        user_id: state,
        provider: "google_analytics",
        access_token: tokenData.access_token,
        refresh_token: tokenData.refresh_token ?? null,
        is_active: true,
        metadata,
      },
      { onConflict: "user_id,provider" },
    );

  if (upsertError) {
    console.error("ga4-oauth: failed to upsert integration row", upsertError);
    return Response.redirect(`${siteUrl}/integrations?ga4=error`, 302);
  }

  return Response.redirect(`${siteUrl}/integrations?ga4=connected`, 302);
});

/**
 * fetch-analytics — Edge Function
 *
 * Fetches GA4 analytics data for a given URL using the user's stored GA4 OAuth token.
 * Called on demand via supabase.functions.invoke (not a cron job).
 *
 * Auth: Bearer JWT (user's Supabase token)
 * Body: { url: string }
 *
 * Returns:
 *   { connected: false }                                  — no active GA4 integration
 *   { connected: true, error: string }                    — token expired or API error
 *   { connected: true, setup_required: true }             — no GA4 property ID configured
 *   { connected: true, metrics: AnalyticsMetricsPayload } — success
 *
 * Required env vars:
 *   SUPABASE_URL               — Supabase project URL (auto-injected)
 *   SUPABASE_SERVICE_ROLE_KEY  — Service role key (auto-injected)
 *   SUPABASE_ANON_KEY          — Anon key (auto-injected)
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

// ── CORS headers ──────────────────────────────────────────────

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

// ── Response shape ─────────────────────────────────────────────

interface AnalyticsMetricsPayload {
  url: string;
  pageviews: number;
  bounce_rate: number;
  avg_session_duration: number;
  conversion_rate: number | null;
  period: string;
}

interface FetchAnalyticsResult {
  connected: boolean;
  setup_required?: boolean;
  error?: string;
  metrics?: AnalyticsMetricsPayload;
}

// ── GA4 Reporting API response shapes ─────────────────────────

interface Ga4MetricValue {
  value: string;
}

interface Ga4Row {
  metricValues: Ga4MetricValue[];
}

interface Ga4ReportResponse {
  rows?: Ga4Row[];
  error?: { message?: string; code?: number };
}

// ── Handler ───────────────────────────────────────────────────

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method not allowed" }), {
      status: 405,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  const anonKey = Deno.env.get("SUPABASE_ANON_KEY") ?? "";

  // ── Authenticate user via Bearer JWT ──────────────────────────
  const authHeader = req.headers.get("Authorization");
  if (!authHeader?.startsWith("Bearer ")) {
    return new Response(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  const jwt = authHeader.slice(7);

  // Verify JWT by creating a user-context client
  const userClient = createClient(supabaseUrl, anonKey, {
    global: { headers: { Authorization: `Bearer ${jwt}` } },
  });

  const { data: { user }, error: authError } = await userClient.auth.getUser();
  if (authError || !user) {
    return new Response(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  // ── Parse request body ─────────────────────────────────────────
  let body: { url?: string };
  try {
    body = (await req.json()) as { url?: string };
  } catch {
    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
      status: 400,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  if (!body.url || typeof body.url !== "string") {
    return new Response(JSON.stringify({ error: "url is required" }), {
      status: 400,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }

  const targetUrl = body.url;

  // ── Fetch GA4 integration (service role to bypass RLS) ─────────
  const adminClient = createClient(supabaseUrl, serviceRoleKey);

  const { data: integration, error: integrationError } = await adminClient
    .from("integrations")
    .select("access_token, refresh_token, metadata")
    .eq("user_id", user.id)
    .eq("provider", "google_analytics")
    .eq("is_active", true)
    .maybeSingle();

  if (integrationError) {
    console.error("fetch-analytics: integration query error", integrationError);
    return jsonResponse<FetchAnalyticsResult>({ connected: false });
  }

  if (!integration || !integration.access_token) {
    return jsonResponse<FetchAnalyticsResult>({ connected: false });
  }

  // ── Check for GA4 property ID in metadata ─────────────────────
  const metadata = (integration.metadata ?? {}) as Record<string, unknown>;
  const propertyId = typeof metadata.ga4_property_id === "string"
    ? metadata.ga4_property_id
    : null;

  if (!propertyId) {
    return jsonResponse<FetchAnalyticsResult>({
      connected: true,
      setup_required: true,
    });
  }

  // ── Call GA4 Data API (Reporting API v4) ───────────────────────
  // TODO: Implement full GA4 Data API call once property ID setup flow is complete.
  // For v1, we return mock data when a property ID is present, to unblock the UI.
  // Replace the block below with a real fetch to:
  //   POST https://analyticsdata.googleapis.com/v1beta/properties/{propertyId}:runReport
  // with Authorization: Bearer {access_token}

  try {
    const ga4Url = `https://analyticsdata.googleapis.com/v1beta/properties/${propertyId}:runReport`;

    // Extract pathname for page filter
    let pagePath = "/";
    try {
      pagePath = new URL(targetUrl).pathname || "/";
    } catch {
      // fallback to root
    }

    const reportBody = {
      dateRanges: [{ startDate: "30daysAgo", endDate: "today" }],
      dimensions: [{ name: "pagePath" }],
      metrics: [
        { name: "sessions" },
        { name: "bounceRate" },
        { name: "averageSessionDuration" },
        { name: "conversions" },
      ],
      dimensionFilter: {
        filter: {
          fieldName: "pagePath",
          stringFilter: {
            matchType: "BEGINS_WITH",
            value: pagePath,
          },
        },
      },
    };

    const ga4Res = await fetch(ga4Url, {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${integration.access_token}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(reportBody),
    });

    const ga4Data = (await ga4Res.json()) as Ga4ReportResponse;

    if (!ga4Res.ok || ga4Data.error) {
      const errMsg = ga4Data.error?.message ?? "GA4 API error";
      const isTokenExpired = ga4Data.error?.code === 401;
      return jsonResponse<FetchAnalyticsResult>({
        connected: true,
        error: isTokenExpired
          ? "Token expired. Please reconnect your Google Analytics account."
          : errMsg,
      });
    }

    // Parse first matching row (aggregate over the page path)
    const row = ga4Data.rows?.[0];
    const metrics: AnalyticsMetricsPayload = {
      url: targetUrl,
      pageviews: row ? Math.round(parseFloat(row.metricValues[0]?.value ?? "0")) : 0,
      bounce_rate: row ? parseFloat((parseFloat(row.metricValues[1]?.value ?? "0") * 100).toFixed(1)) : 0,
      avg_session_duration: row ? Math.round(parseFloat(row.metricValues[2]?.value ?? "0")) : 0,
      conversion_rate: row ? parseFloat((parseFloat(row.metricValues[3]?.value ?? "0")).toFixed(2)) : null,
      period: "Last 30 days",
    };

    return jsonResponse<FetchAnalyticsResult>({ connected: true, metrics });
  } catch (err) {
    console.error("fetch-analytics: GA4 API fetch failed", err);
    return jsonResponse<FetchAnalyticsResult>({
      connected: true,
      error: "Failed to fetch analytics data. Please try again.",
    });
  }
});

// ── Helper ─────────────────────────────────────────────────────

function jsonResponse<T>(data: T, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

import { useQuery } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import type { AnalyticsMetrics } from "@/types/index";
import { useIntegrations } from "./use-integrations";

// ── Query keys ─────────────────────────────────────────────────

export const analyticsKeys = {
  all: ["analytics"] as const,
  byUrl: (url: string) => ["analytics", url] as const,
};

// ── Edge function response shapes ─────────────────────────────

interface AnalyticsNotConnected {
  connected: false;
}

interface AnalyticsSetupRequired {
  connected: true;
  setup_required: true;
}

interface AnalyticsError {
  connected: true;
  error: string;
}

interface AnalyticsSuccess {
  connected: true;
  metrics: AnalyticsMetrics;
}

type FetchAnalyticsResponse =
  | AnalyticsNotConnected
  | AnalyticsSetupRequired
  | AnalyticsError
  | AnalyticsSuccess;

// ── useGa4Connection ───────────────────────────────────────────
// Returns whether the current user has an active GA4 integration.

export function useGa4Connection(): {
  isConnected: boolean;
  isLoading: boolean;
} {
  const { data: integrations = [], isLoading } = useIntegrations();

  const isConnected = integrations.some(
    (i) => i.provider === "google_analytics" && i.is_active,
  );

  return { isConnected, isLoading };
}

// ── useAnalyticsData ───────────────────────────────────────────
// Fetches GA4 analytics for the given URL.
// Returns null when GA4 is not connected or when there is no data.

export function useAnalyticsData(url: string): {
  data: AnalyticsMetrics | null;
  isLoading: boolean;
  isError: boolean;
  setupRequired: boolean;
  errorMessage: string | null;
  notConnected: boolean;
} {
  const { isConnected } = useGa4Connection();

  const query = useQuery({
    queryKey: analyticsKeys.byUrl(url),
    queryFn: async (): Promise<FetchAnalyticsResponse> => {
      const { data, error } = await supabase.functions.invoke<FetchAnalyticsResponse>(
        "fetch-analytics",
        { body: { url } },
      );

      if (error) throw new Error(error.message);
      if (!data) throw new Error("Empty response from fetch-analytics");
      return data;
    },
    enabled: isConnected && url.length > 0,
    staleTime: 1000 * 60 * 5, // 5 minutes — GA4 data doesn't change per second
    retry: 1,
  });

  const response = query.data;

  if (!response) {
    return {
      data: null,
      isLoading: query.isLoading,
      isError: query.isError,
      setupRequired: false,
      errorMessage: null,
      notConnected: !isConnected,
    };
  }

  if (!response.connected) {
    return {
      data: null,
      isLoading: false,
      isError: false,
      setupRequired: false,
      errorMessage: null,
      notConnected: true,
    };
  }

  if ("setup_required" in response && response.setup_required) {
    return {
      data: null,
      isLoading: false,
      isError: false,
      setupRequired: true,
      errorMessage: null,
      notConnected: false,
    };
  }

  if ("error" in response && response.error) {
    return {
      data: null,
      isLoading: false,
      isError: true,
      setupRequired: false,
      errorMessage: response.error,
      notConnected: false,
    };
  }

  if ("metrics" in response && response.metrics) {
    return {
      data: response.metrics,
      isLoading: false,
      isError: false,
      setupRequired: false,
      errorMessage: null,
      notConnected: false,
    };
  }

  return {
    data: null,
    isLoading: false,
    isError: false,
    setupRequired: false,
    errorMessage: null,
    notConnected: false,
  };
}

