// ── Metrics display ────────────────────────────────────────────

function MetricsDisplay({ metrics }: { metrics: AnalyticsMetrics }) {
  const formatDuration = (seconds: number): string => {
    if (seconds < 60) return `${seconds}s`;
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return secs > 0 ? `${mins}m ${secs}s` : `${mins}m`;
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.4, ease: "easeOut" }}
    >
      <Card className="border-border/50 shadow-soft">
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm font-semibold">
              Real Conversion Data (GA4)
            </CardTitle>
            <Badge
              variant="outline"
              className="border-orange-200 bg-orange-50 text-orange-700 text-xs"
            >
              <BarChart2 className="mr-1 h-3 w-3" />
              {metrics.period}
            </Badge>
          </div>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
            <MetricCard
              icon={<BarChart2 className="h-3.5 w-3.5" />}
              label="Pageviews"
              value={metrics.pageviews.toLocaleString()}
              subLabel="sessions"
            />
            <MetricCard
              icon={<TrendingDown className="h-3.5 w-3.5" />}
              label="Bounce Rate"
              value={`${metrics.bounce_rate}%`}
              subLabel={
                metrics.bounce_rate > 60
                  ? "High — needs attention"
                  : metrics.bounce_rate > 40
                  ? "Average"
                  : "Good"
              }
            />
            <MetricCard
              icon={<Clock className="h-3.5 w-3.5" />}
              label="Avg. Duration"
              value={formatDuration(metrics.avg_session_duration)}
              subLabel="per session"
            />
            <MetricCard
              icon={<Target className="h-3.5 w-3.5" />}
              label="Conversions"
              value={
                metrics.conversion_rate !== null
                  ? `${metrics.conversion_rate}%`
                  : "—"
              }
              subLabel={
                metrics.conversion_rate !== null ? "conversion rate" : "not tracked"
              }
            />
          </div>
        </CardContent>
      </Card>
    </motion.div>
  );
}

// ── Main component ─────────────────────────────────────────────

export function AnalyticsCorrelation({ url }: AnalyticsCorrelationProps) {
  const { isConnected, isLoading: connectionLoading } = useGa4Connection();
  const { data, isLoading, isError, setupRequired, errorMessage, notConnected } =
    useAnalyticsData(url);

  // While checking connection status
  if (connectionLoading) {
    return <AnalyticsSkeleton />;
  }

  // Not connected to GA4
  if (!isConnected || notConnected) {
    return <NotConnectedState />;
  }

  // Connected but GA4 property ID not configured
  if (setupRequired) {
    return <SetupRequiredState />;
  }

  // Loading analytics data
  if (isLoading) {
    return <AnalyticsSkeleton />;
  }

  // API error or token expired
  if (isError || errorMessage) {
    return <ErrorMessageState message={errorMessage ?? "Unable to load analytics data."} />;
  }

  // No data available for this URL
  if (!data) {
    return (
      <Card className="border-border/50 shadow-soft">
        <CardContent className="flex items-center gap-3 py-6">
          <BarChart2 className="h-5 w-5 shrink-0 text-muted-foreground" />
          <p className="text-sm text-muted-foreground">
            No GA4 data available for this URL in the last 30 days.
          </p>
        </CardContent>
      </Card>
    );
  }

  return <MetricsDisplay metrics={data} />;
}

